<?php
require_once __DIR__ . '/../includes.php'; if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}
$id=(int)($_GET['id']??0);$post=null;if($id){$q=db()->prepare('SELECT * FROM posts WHERE id=?');$q->execute([$id]);$post=$q->fetch();if(!$post){http_response_code(404);exit('المقال غير موجود.');}}
$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim((string)($_POST['title']??''));$slug=trim((string)($_POST['slug']??''));$slug=trim(preg_replace('/[^\pL\pN-]+/u','-',mb_strtolower($slug))??'','-');$category=trim((string)($_POST['category']??''));$author=trim((string)($_POST['author']??''));$excerpt=trim((string)($_POST['excerpt']??''));$content=trim((string)($_POST['content']??''));$cover=trim((string)($_POST['cover_url']??''));$status=($_POST['status']??'draft')==='published'?'published':'draft';if($title===''||$slug===''||$category===''||$author===''||$content==='')$error='العنوان والرابط والتصنيف والكاتب والمحتوى مطلوبة.';elseif($cover!==''&&!filter_var($cover,FILTER_VALIDATE_URL))$error='رابط الصورة غير صالح.';else{try{if($id){$q=db()->prepare('UPDATE posts SET title=?,slug=?,category=?,author=?,excerpt=?,content=?,cover_url=?,status=? WHERE id=?');$q->execute([$title,$slug,$category,$author,$excerpt,$content,$cover,$status,$id]);}else{$q=db()->prepare('INSERT INTO posts(title,slug,category,author,excerpt,content,cover_url,status) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$title,$slug,$category,$author,$excerpt,$content,$cover,$status]);}header('Location: index.php?saved=1');exit;}catch(PDOException $e){$error='تعذر الحفظ. تحقق من أن رابط المقال (slug) غير مستخدم.';}}}
$v=$post??['title'=>'','slug'=>'','category'=>'علوم','author'=>'فريق التحرير','excerpt'=>'','content'=>'','cover_url'=>'','status'=>'draft'];
?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $id?'تعديل':'مقال جديد' ?> | الإدارة</title><link rel="stylesheet" href="../assets/site.css"><main class="admin-wrap"><p><a href="index.php">← لوحة الإدارة</a></p><section class="panel"><h1><?=$id?'تعديل المقال':'إنشاء مقال'?></h1><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>عنوان المقال<input name="title" required maxlength="240" value="<?=e($v['title'])?>"></label><label>رابط المقال (slug)<input name="slug" required value="<?=e($v['slug'])?>"><small>اكتب رابطًا قصيرًا مثل: ai-future أو مستقبل-الذكاء</small></label><div class="two"><label>التصنيف<input name="category" required value="<?=e($v['category'])?>"></label><label>الكاتب<input name="author" required value="<?=e($v['author'])?>"></label></div><label>موجز المقال<textarea name="excerpt" rows="3"><?=e($v['excerpt'])?></textarea></label><label>رابط صورة الغلاف (اختياري)<input type="url" name="cover_url" value="<?=e($v['cover_url'])?>"></label><label>نص المقال<textarea name="content" rows="16" required><?=e($v['content'])?></textarea><small>أدخل نصًا عاديًا. افصل الفقرات بسطر فارغ.</small></label><label>الحالة<select name="status"><option value="draft" <?=$v['status']==='draft'?'selected':''?>>مسودة</option><option value="published" <?=$v['status']==='published'?'selected':''?>>منشور</option></select></label><button class="btn">حفظ المقال</button></form></section></main></html>
